import type { Account, Category, Recurrence, CalendarEntry, FinancialCalendar, SubscriptionRadar } from '../../src/features/finance/contracts.generated';
const instant='2026-10-02T12:00:00.000Z';
export const accountFixture:Account={id:'22222222-2222-4222-8222-222222222222',name:'Conta BRL',type:'checking',currency:'BRL',initialBalanceMinor:'100000',balanceMinor:'100000',isActive:true,createdAt:instant,updatedAt:instant};
export const categoryFixture:Category={id:'33333333-3333-4333-8333-333333333333',name:'Serviços',kind:'EXPENSE',isActive:true,createdAt:instant,updatedAt:instant};
export function recurrenceFixture(patch:Partial<Recurrence>={}):Recurrence {return {id:'44444444-4444-4444-8444-444444444444',name:'Assinatura teste',description:null,transactionType:'EXPENSE',recurrenceKind:'SUBSCRIPTION',amountMinor:'10000',currency:'BRL',accountId:null,categoryId:null,frequency:'MONTHLY',intervalCount:1,startDate:'2026-10-31',endDate:null,status:'ACTIVE',createdAt:instant,updatedAt:instant,archivedAt:null,account:null,category:null,nextOccurrenceDate:'2026-10-31',today:'2026-10-02',timeZone:'America/Sao_Paulo',...patch};}
export function entryFixture(row=recurrenceFixture(),date='2026-10-31'):CalendarEntry {return {recurrenceId:row.id,occurrenceKey:row.id+':'+date,date,name:row.name,transactionType:row.transactionType,recurrenceKind:row.recurrenceKind,amountMinor:row.amountMinor,currency:row.currency,account:row.account,category:row.category};}
export function calendarFixture(entries:CalendarEntry[]=[],from='2026-10-01',to='2026-11-01'):FinancialCalendar {
  const sums=new Map<Recurrence['currency'],{income:bigint;expense:bigint}>();for(const e of entries){const value=sums.get(e.currency)??{income:0n,expense:0n};if(e.transactionType==='INCOME')value.income+=BigInt(e.amountMinor);else value.expense+=BigInt(e.amountMinor);sums.set(e.currency,value);}
  return {from,to,today:'2026-10-02',timeZone:'America/Sao_Paulo',entries,totals:[...sums].map(([currency,v])=>({currency,incomeMinor:String(v.income),expenseMinor:String(v.expense),projectedNetMinor:String(v.income-v.expense)}))};
}
export function radarFixture(subscriptions:Recurrence[]=[],entries:CalendarEntry[]=[]):SubscriptionRadar {return {from:'2026-10-02',to:'2026-11-01',today:'2026-10-02',timeZone:'America/Sao_Paulo',subscriptions,entries,totals:[...new Set(subscriptions.map(r=>r.currency))].map(currency=>({currency,subscriptionCount:subscriptions.filter(r=>r.currency===currency).length,occurrenceCount:entries.filter(e=>e.currency===currency).length,amountMinor:String(entries.filter(e=>e.currency===currency).reduce((sum,e)=>sum+BigInt(e.amountMinor),0n))}))};}
